package cn.xuexizhitu.service;
import cn.xuexizhitu.common.*;
import static cn.xuexizhitu.common.BusinessData.*;
import cn.xuexizhitu.repository.*;
import cn.xuexizhitu.validation.BusinessInput;
import cn.xuexizhitu.security.CurrentUser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import java.math.*;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PlanService {
    private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final LearningRepository learning;private final AdminService courses;private final BusinessInput input;private final AuditRepository audit;
    private JsonNode parse(Object v){try{return mapper.readTree(v.toString());}catch(Exception e){throw new IllegalStateException(e);}}
    private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}
    private Map<String,Object> owned(String id,boolean lock){return jdbc.queryForList("SELECT p.*,cr.revision_no FROM learning_plan p JOIN plan_current_revision cr ON cr.plan_id=p.id WHERE p.id=? AND p.user_id=?"+(lock?" FOR UPDATE":""),id,CurrentUser.idOrThrow()).stream().findFirst().orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND));}
    private Map<LocalDate,Integer> capacities(JsonNode config){Map<LocalDate,Integer> result=new TreeMap<>();for(JsonNode c:config.path("dayCapacities"))require(result.put(LocalDate.parse(str(c,"day")),c.path("capacityMinutes").asInt())==null,ErrorCode.INVALID_RELATION,"每日容量日期重复");return result;}
    private void validateConfig(JsonNode c){input.validate("PlanConfig",c);LocalDate start=LocalDate.parse(str(c,"startDate")),end=LocalDate.parse(str(c,"endDate"));require(!end.isBefore(start)&&java.time.temporal.ChronoUnit.DAYS.between(start,end)<=3660,ErrorCode.INVALID_RELATION,"计划日期范围无效或超过十年");Set<String> scope=new HashSet<>();c.path("courseScope").forEach(n->scope.add(n.asText()));Set<String> priority=new HashSet<>();c.path("coursePriority").forEach(n->priority.add(n.asText()));require(scope.equals(priority),ErrorCode.INVALID_RELATION,"科目优先级须完整覆盖所选科目");for(String course:scope){learning.course(course);learning.requireCycleCourse(course,str(c,"cycleId"));}for(LocalDate day:capacities(c).keySet())require(!day.isBefore(start)&&!day.isAfter(end),ErrorCode.INVALID_RELATION,"容量日期不在计划范围");if(weekly(c)){require(java.time.temporal.ChronoUnit.DAYS.between(start,end)==34&&scope.size()==4,ErrorCode.INVALID_RELATION,"五周计划须为完整35天及4门理论课");for(String course:scope)require(learning.course(course).type()==cn.xuexizhitu.dto.LearningDtos.CourseType.THEORY,ErrorCode.INVALID_RELATION,"五周计划只选择4门理论课，实践科目请单独安排");require(capacities(c).size()==35,ErrorCode.INVALID_RELATION,"五周计划须逐日配置全部35天容量");}}
    private LocalDate deadline(String course,String cycle){return jdbc.queryForObject("SELECT exam_date FROM cycle_course WHERE course_id=? AND cycle_id=?",(r,i)->r.getDate(1)==null?null:r.getDate(1).toLocalDate(),course,cycle);}
    private List<Map<String,Object>> sourceTasks(JsonNode c){List<Map<String,Object>> tasks=new ArrayList<>();String user=CurrentUser.idOrThrow();for(JsonNode course:c.path("coursePriority")){var row=learning.course(course.asText());require(row.releaseId()!=null,ErrorCode.INVALID_RELATION,"所选科目没有已发布内容");String id=row.id(),release=row.releaseId();for(var r:jdbc.queryForList("SELECT i.*,COALESCE(p.completed,false) completed,p.completed_at FROM item_revision i JOIN chapter_revision ch ON ch.release_id=i.release_id AND ch.chapter_id=i.chapter_id LEFT JOIN user_item_progress p ON p.item_id=i.item_id AND p.user_id=? WHERE i.release_id=? ORDER BY ch.sort_order,ch.chapter_id,i.sort_order,i.item_id",user,release)){tasks.add(obj("id",uuid(),"courseId",id,"itemId",r.get("item_id"),"templateId",null,"kind","ITEM","title",r.get("title"),"estimatedMinutes",r.get("estimated_minutes"),"releaseId",release,"completed",bool(r.get("completed")),"completedAt",AdminService.instant(r,"completed_at"),"target",navigation(row.code(),(String)r.get("chapter_id"),(String)r.get("item_id"),"CATALOG")));}for(var t:jdbc.queryForList("SELECT * FROM plan_task_template WHERE release_id=? AND course_id=? ORDER BY sort_order,id",release,id))tasks.add(obj("id",uuid(),"courseId",id,"itemId",null,"templateId",t.get("id"),"kind",t.get("kind"),"title",t.get("title"),"estimatedMinutes",t.get("estimated_minutes"),"releaseId",release,"completed",false,"completedAt",null,"target",navigation(row.code(),null,null,t.get("kind").equals("PAPER")?"EXAMS":"KNOWLEDGE")));}if(weekly(c))for(JsonNode course:c.path("coursePriority")){String courseId=course.asText();if(tasks.stream().noneMatch(t->courseId.equals(t.get("courseId"))&&!"ITEM".equals(t.get("kind")))){var row=learning.course(courseId);tasks.add(obj("id",uuid(),"courseId",courseId,"itemId",null,"templateId",null,"kind","REVIEW","title",row.name()+" · 真题与错题复习（计划估时60分钟）","estimatedMinutes",60,"releaseId",row.releaseId(),"completed",false,"completedAt",null,"target",navigation(row.code(),null,null,"PRACTICE")));}}return tasks;}
    private Object navigation(String code,String chapter,String item,String pane){return obj("pane",pane,"courseCode",code,"chapterId",chapter,"itemId",item,"questionId",null);}
    private List<Map<String,Object>> allTasks(String plan){return jdbc.queryForList("SELECT t.*,c.code,i.chapter_id,CASE WHEN t.kind='ITEM' THEN COALESCE(p.completed,false) ELSE t.completed END effective_completed,CASE WHEN t.kind='ITEM' THEN p.completed_at ELSE t.completed_at END effective_at FROM plan_task t JOIN course c ON c.id=t.course_id LEFT JOIN study_item i ON i.id=t.item_id LEFT JOIN user_item_progress p ON p.item_id=t.item_id AND p.user_id=? WHERE t.plan_id=? ORDER BY t.id",CurrentUser.idOrThrow(),plan).stream().map(t->obj("id",t.get("id"),"courseId",t.get("course_id"),"itemId",t.get("item_id"),"templateId",t.get("template_id"),"kind",t.get("kind"),"title",t.get("title_snapshot"),"estimatedMinutes",t.get("estimated_minutes"),"releaseId",t.get("release_id"),"completed",bool(t.get("effective_completed")),"completedAt",AdminService.instant(t,"effective_at"),"target",navigation((String)t.get("code"),(String)t.get("chapter_id"),(String)t.get("item_id"),t.get("kind").equals("ITEM")?"CATALOG":t.get("kind").equals("PAPER")?"EXAMS":t.get("template_id")==null?"PRACTICE":"KNOWLEDGE"))).toList();}
    private List<Map<String,Object>> scopedTasks(JsonNode snapshot,List<Map<String,Object>> all){
        if(!snapshot.has("taskIds"))return all;
        Map<String,Map<String,Object>> byId=new HashMap<>();all.forEach(t->byId.put((String)t.get("id"),t));
        List<Map<String,Object>> result=new ArrayList<>();for(JsonNode id:snapshot.path("taskIds")){var t=byId.get(id.asText());if(t!=null)result.add(t);}return result;
    }
    private List<Map<String,Object>> tasks(String plan){var p=owned(plan,false);String snapshot=jdbc.queryForObject("SELECT snapshot FROM plan_revision WHERE plan_id=? AND revision_no=?",String.class,plan,p.get("revision_no"));return scopedTasks(parse(snapshot),allTasks(plan));}
    private void taskIds(String id,int revision,List<Map<String,Object>> tasks){String raw=jdbc.queryForObject("SELECT snapshot FROM plan_revision WHERE plan_id=? AND revision_no=?",String.class,id,revision);ObjectNode snapshot=(ObjectNode)parse(raw);snapshot.set("taskIds",mapper.valueToTree(tasks.stream().map(t->t.get("id")).toList()));jdbc.update("UPDATE plan_revision SET snapshot=? WHERE plan_id=? AND revision_no=?",json(snapshot),id,revision);}
    private boolean weekly(JsonNode config){return config.path("strategy").asText().equals("WEEKLY_35");}
    private List<Map<String,Object>> allocate(JsonNode config,List<Map<String,Object>> tasks,LocalDate earliest){
        LocalDate start=LocalDate.parse(str(config,"startDate"));
        if(weekly(config)){
            List<String> priority=new ArrayList<>();config.path("coursePriority").forEach(c->priority.add(c.asText()));
            var work=tasks.stream().map(t->new WeeklyPlanAllocator.Work(new PlanAllocator.Work((String)t.get("id"),((Number)t.get("estimatedMinutes")).intValue(),deadline((String)t.get("courseId"),str(config,"cycleId"))),(String)t.get("courseId"),(String)t.get("kind"))).toList();
            return WeeklyPlanAllocator.allocate(work,priority,capacities(config),Map.of(),start,earliest,0);
        }
        var work=tasks.stream().map(t->new PlanAllocator.Work((String)t.get("id"),((Number)t.get("estimatedMinutes")).intValue(),deadline((String)t.get("courseId"),str(config,"cycleId")))).toList();
        return PlanAllocator.allocate(work,capacities(config),Map.of(),earliest.isAfter(start)?earliest:start,LocalDate.parse(str(config,"endDate")),0);
    }
    private Map<String,Object> assemble(String id,int revision,JsonNode config,List<Map<String,Object>> tasks,List<Map<String,Object>> segments,Instant created,Instant confirmed){Map<String,Map<String,Object>> taskMap=new HashMap<>();tasks.forEach(t->taskMap.put((String)t.get("id"),t));List<Map<String,Object>> days=new ArrayList<>(),unscheduled=new ArrayList<>(),awaiting=new ArrayList<>();Map<LocalDate,Integer> caps=capacities(config);LocalDate start=LocalDate.parse(str(config,"startDate")),end=LocalDate.parse(str(config,"endDate"));int total=0,completed=0,overdue=0,completedDays=0;for(var t:tasks){total+=((Number)t.get("estimatedMinutes")).intValue();if(Boolean.TRUE.equals(t.get("completed")))completed+=((Number)t.get("estimatedMinutes")).intValue();}for(var s:segments){if(s.get("state").equals("UNSCHEDULED"))unscheduled.add(s);if(s.get("state").equals("AWAITING_DATE"))awaiting.add(s);if(s.get("scheduledOn")!=null&&LocalDate.parse(s.get("scheduledOn").toString()).isBefore(today())&&!Boolean.TRUE.equals(taskMap.get(s.get("taskId")).get("completed")))overdue+=((Number)s.get("minutes")).intValue();}
        for(LocalDate date=start;!date.isAfter(end);date=date.plusDays(1)){String day=date.toString();List<Map<String,Object>> scheduled=segments.stream().filter(s->day.equals(s.get("scheduledOn"))).toList();int used=scheduled.stream().mapToInt(s->((Number)s.get("minutes")).intValue()).sum();int done=scheduled.stream().filter(s->Boolean.TRUE.equals(taskMap.get(s.get("taskId")).get("completed"))).mapToInt(s->((Number)s.get("minutes")).intValue()).sum();if(used>0&&used==done)completedDays++;days.add(obj("day",day,"capacityMinutes",caps.getOrDefault(date,0),"reservedMinutes",used,"remainingMinutes",Math.max(0,caps.getOrDefault(date,0)-used),"segments",scheduled,"completedMinutes",done,"percent",percent(done,used)));}
        List<Map<String,Object>> weeks=new ArrayList<>();for(int offset=0,index=1;offset<days.size();offset+=7,index++){var week=days.subList(offset,Math.min(offset+7,days.size()));int used=week.stream().mapToInt(d->((Number)d.get("reservedMinutes")).intValue()).sum(),done=week.stream().mapToInt(d->((Number)d.get("completedMinutes")).intValue()).sum();weeks.add(obj("index",index,"startDate",week.get(0).get("day"),"endDate",week.get(week.size() - 1).get("day"),"scheduledMinutes",used,"completedMinutes",done,"percent",percent(done,used)));}
        List<Object> summaries=new ArrayList<>();for(JsonNode course:config.path("courseScope"))summaries.add(courses.courseDto(course.asText(),str(config,"cycleId")));
        return obj("id",id,"revision",revision,"config",config,"tasks",tasks,"days",days,"unscheduled",unscheduled,"awaitingDate",awaiting,"progress",obj("completedMinutes",completed,"totalEstimatedMinutes",total,"percent",percent(completed,total)),"createdAt",created,"confirmedAt",confirmed,"asOf",Instant.now(),"weeks",weeks,"completedDayCount",completedDays,"dayCount",days.size(),"overdueUncompletedMinutes",overdue,"courseSummaries",summaries);}
    private int percent(int done,int total){return total==0?0:(int)Math.round(done*100.0/total);}
    private void saveRevision(String id,int revision,JsonNode config,List<Map<String,Object>> segments,Instant at){jdbc.update("INSERT INTO plan_revision(plan_id,revision_no,snapshot,confirmed_at) VALUES(?,?,?,?)",id,revision,json(obj("config",config)),LocalDateTime.ofInstant(at,ZoneOffset.UTC));for(var c:capacities(config).entrySet())jdbc.update("INSERT INTO plan_day_capacity(plan_id,revision_no,day,capacity_minutes) VALUES(?,?,?,?)",id,revision,c.getKey(),c.getValue());for(var s:segments)jdbc.update("INSERT INTO plan_task_segment(id,plan_id,revision_no,task_id,scheduled_on,minutes,state,sort_order) VALUES(?,?,?,?,?,?,?,?)",s.get("id"),id,revision,s.get("taskId"),s.get("scheduledOn"),s.get("minutes"),s.get("state"),s.get("sortOrder"));jdbc.update("INSERT INTO plan_current_revision(plan_id,revision_no) VALUES(?,?) ON DUPLICATE KEY UPDATE revision_no=VALUES(revision_no)",id,revision);}
    @Transactional public Object create(JsonNode w){input.validate("PlanCreate",w);JsonNode config=w.path("config");validateConfig(config);String user=CurrentUser.idOrThrow();learning.lockUser(user);List<Map<String,Object>> tasks=sourceTasks(config);List<Map<String,Object>> segments=allocate(config,tasks,LocalDate.parse(str(config,"startDate")));int gap=segments.stream().filter(s->!s.get("state").equals("SCHEDULED")).mapToInt(s->((Number)s.get("minutes")).intValue()).sum();require(gap==0||w.path("acceptUnscheduled").asBoolean(),ErrorCode.PLAN_GAP,"计划未排入"+gap+"分钟，请调整配置或明确接受");String id=uuid();Instant now=Instant.now();jdbc.update("INSERT INTO learning_plan(id,user_id,cycle_id,start_date,end_date,config_snapshot,created_at) VALUES(?,?,?,?,?,?,?)",id,user,str(config,"cycleId"),str(config,"startDate"),str(config,"endDate"),json(config),LocalDateTime.ofInstant(now,ZoneOffset.UTC));for(var t:tasks)jdbc.update("INSERT INTO plan_task(id,plan_id,course_id,item_id,template_id,title_snapshot,estimated_minutes,release_id,kind,completed,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",t.get("id"),id,t.get("courseId"),t.get("itemId"),t.get("templateId"),t.get("title"),t.get("estimatedMinutes"),t.get("releaseId"),t.get("kind"),t.get("completed"),t.get("completedAt")==null?null:LocalDateTime.ofInstant((Instant)t.get("completedAt"),ZoneOffset.UTC));saveRevision(id,1,config,segments,now);taskIds(id,1,tasks);return get(id,null);}
    private List<Map<String,Object>> segments(String id,int revision){return jdbc.queryForList("SELECT * FROM plan_task_segment WHERE plan_id=? AND revision_no=? ORDER BY sort_order,id",id,revision).stream().map(s->obj("id",s.get("id"),"taskId",s.get("task_id"),"scheduledOn",s.get("scheduled_on")==null?null:s.get("scheduled_on").toString(),"minutes",s.get("minutes"),"state",s.get("state"),"sortOrder",s.get("sort_order"))).toList();}
    public Map<String,Object> get(String id,Integer revision){var p=owned(id,false);int no=revision==null?((Number)p.get("revision_no")).intValue():revision;var rows=jdbc.queryForList("SELECT snapshot,confirmed_at FROM plan_revision WHERE plan_id=? AND revision_no=?",id,no);require(!rows.isEmpty(),ErrorCode.NOT_FOUND,"计划版本不存在");JsonNode snapshot=parse(rows.get(0).get("snapshot"));JsonNode config=snapshot.path("config");return assemble(id,no,config,scopedTasks(snapshot,allTasks(id)),segments(id,no),AdminService.instant(p,"created_at"),AdminService.instant(rows.get(0),"confirmed_at"));}
    public Object list(String cycle,int page,int size){String sql=" FROM learning_plan WHERE user_id=?";List<Object> args=new ArrayList<>(List.of(CurrentUser.idOrThrow()));if(cycle!=null){learning.requireCycle(cycle);sql+=" AND cycle_id=?";args.add(cycle);}long total=jdbc.queryForObject("SELECT COUNT(*)"+sql,Long.class,args.toArray());args.add(size);args.add((page-1L)*size);var items=jdbc.queryForList("SELECT id"+sql+" ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",String.class,args.toArray()).stream().map(id->{var p=get(id,null);JsonNode config=mapper.valueToTree(p.get("config"));return obj("id",id,"cycleId",str(config,"cycleId"),"startDate",str(config,"startDate"),"endDate",str(config,"endDate"),"revision",p.get("revision"),"completedPercent",((Map<?,?>)p.get("progress")).get("percent"));}).toList();return obj("items",items,"page",page,"size",size,"total",total);}
    @Transactional public Object complete(String id,String task,JsonNode w){input.validate("TaskCompletionWrite",w);String user=CurrentUser.idOrThrow();learning.lockUser(user);var p=owned(id,true);require(((Number)p.get("revision_no")).intValue()==w.path("baseRevision").asInt(),ErrorCode.CONFLICT,"计划版本已变化");var t=tasks(id).stream().filter(r->r.get("id").equals(task)).findFirst().orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND));require(t.get("completed").equals(w.path("expectedCompleted").asBoolean()),ErrorCode.CONFLICT,"任务完成状态已变化");String course=(String)t.get("courseId");List<String> affected;
        if(t.get("kind").equals("ITEM")){require(!w.path("expectedItemRevision").isNull(),ErrorCode.INVALID_RELATION,"目录任务需提供条目修订号");String release=learning.course(course).releaseId();require(release!=null&&jdbc.queryForObject("SELECT COUNT(*) FROM item_revision WHERE item_id=? AND release_id=?",Integer.class,t.get("itemId"),release)>0,ErrorCode.INVALID_RELATION,"条目已从当前目录移除，不能改动其进度");affected=learning.complete(user,release,(String)t.get("itemId"),w.path("completed").asBoolean(),w.path("expectedItemRevision").asLong(),Instant.now());}
        else{require(w.path("expectedItemRevision").isNull(),ErrorCode.INVALID_RELATION,"非目录任务无条目修订号");jdbc.update("UPDATE plan_task SET completed=?,completed_at=? WHERE id=? AND plan_id=?",w.path("completed").asBoolean(),w.path("completed").asBoolean()?LocalDateTime.now(ZoneOffset.UTC):null,task,id);affected=List.of(id);}
        var updated=tasks(id).stream().filter(r->r.get("id").equals(task)).findFirst().orElseThrow();return obj("task",updated,"planRevision",p.get("revision_no"),"courseProgress",learning.progress(user,learning.course(course).releaseId()),"overallProgress",learning.overallProgress(user),"affectedPlanIds",affected,"clientMutationId",str(w,"clientMutationId"),"asOf",Instant.now());}
    private String fingerprint(String id,int revision,JsonNode config,List<Map<String,Object>> tasks){List<Object> exams=new ArrayList<>();for(JsonNode c:config.path("coursePriority"))exams.add(obj("course",c.asText(),"deadline",deadline(c.asText(),str(config,"cycleId"))));try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(json(obj("revision",revision,"today",today(),"config",config,"tasks",tasks,"exams",exams,"capacities",jdbc.queryForList("SELECT day,capacity_minutes FROM plan_day_capacity WHERE plan_id=? AND revision_no=? ORDER BY day",id,revision))).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    @Transactional public Object preview(String id,JsonNode w){input.validate("RescheduleRequest",w);if(w.has("config"))return configurationPreview(id,w);learning.lockUser(CurrentUser.idOrThrow());var original=owned(id,true);int base=((Number)original.get("revision_no")).intValue();require(base==w.path("baseRevision").asInt(),ErrorCode.CONFLICT,"计划版本已变化");var current=get(id,base);ObjectNode config=mapper.valueToTree(current.get("config"));JsonNode oldConfig=config.deepCopy();if(w.has("dayCapacities"))config.set("dayCapacities",w.path("dayCapacities"));if(w.has("coursePriority"))config.set("coursePriority",w.path("coursePriority"));validateConfig(config);var tasks=tasks(id);Map<String,Map<String,Object>> byId=new HashMap<>();tasks.forEach(t->byId.put((String)t.get("id"),t));List<Map<String,Object>> fixed=new ArrayList<>(),moving=new ArrayList<>();Map<LocalDate,Integer> reserved=new HashMap<>();int order=0;
        for(var s:segments(id,base)){if(s.get("scheduledOn")!=null&&LocalDate.parse(s.get("scheduledOn").toString()).isBefore(today())&&!Boolean.TRUE.equals(byId.get(s.get("taskId")).get("completed")))moving.add(s);else{Map<String,Object> copy=new LinkedHashMap<>(s);copy.put("id",uuid());fixed.add(copy);order=Math.max(order,((Number)s.get("sortOrder")).intValue()+1);if(s.get("scheduledOn")!=null)reserved.merge(LocalDate.parse(s.get("scheduledOn").toString()),((Number)s.get("minutes")).intValue(),Integer::sum);}}
        Map<LocalDate,Integer> caps=capacities(config);for(var e:reserved.entrySet())if(!e.getKey().isBefore(today()))require(caps.getOrDefault(e.getKey(),0)>=e.getValue(),ErrorCode.INVALID_RELATION,"新容量不能小于今天或未来已有安排");Map<String,Integer> priority=new HashMap<>();int index=0;for(JsonNode c:config.path("coursePriority"))priority.put(c.asText(),index++);moving.sort(Comparator.<Map<String,Object>,Integer>comparing(s->weekly(config)&&!"ITEM".equals(byId.get(s.get("taskId")).get("kind"))?4:priority.get((String)byId.get(s.get("taskId")).get("courseId"))).thenComparing(s->priority.get((String)byId.get(s.get("taskId")).get("courseId"))).thenComparing(s->((Number)s.get("sortOrder")).intValue()));List<PlanAllocator.Work> work=new ArrayList<>();for(var s:moving)work.add(new PlanAllocator.Work((String)s.get("taskId"),((Number)s.get("minutes")).intValue(),deadline((String)byId.get(s.get("taskId")).get("courseId"),str(config,"cycleId"))));List<Map<String,Object>> added;if(weekly(config)){List<String> courseOrder=new ArrayList<>();config.path("coursePriority").forEach(c->courseOrder.add(c.asText()));List<WeeklyPlanAllocator.Work> weeklyWork=new ArrayList<>();for(var w0:work){var t=byId.get(w0.task());weeklyWork.add(new WeeklyPlanAllocator.Work(w0,(String)t.get("courseId"),(String)t.get("kind")));}added=WeeklyPlanAllocator.allocate(weeklyWork,courseOrder,caps,reserved,LocalDate.parse(str(config,"startDate")),today().plusDays(1),order);}else added=PlanAllocator.allocate(work,caps,reserved,today().plusDays(1),LocalDate.parse(str(config,"endDate")),order);List<Map<String,Object>> all=new ArrayList<>(fixed);all.addAll(added);int gap=added.stream().filter(s->!s.get("state").equals("SCHEDULED")).mapToInt(s->((Number)s.get("minutes")).intValue()).sum();String preview=uuid(),fp=fingerprint(id,base,oldConfig,tasks);List<Map<String,Object>> moves=new ArrayList<>();int allocationIndex=0;for(var old:moving){List<Map<String,Object>> replacements=new ArrayList<>();int remaining=((Number)old.get("minutes")).intValue();while(remaining>0){var replacement=added.get(allocationIndex++);replacements.add(replacement);remaining-=((Number)replacement.get("minutes")).intValue();}moves.add(obj("segmentId",old.get("id"),"fromDate",old.get("scheduledOn"),"toSegments",replacements));}Instant now=Instant.now();var proposed=assemble(id,base+1,config,tasks,all,AdminService.instant(original,"created_at"),null);var result=obj("id",preview,"planId",id,"baseRevision",base,"asOf",today(),"inputFingerprint",fp,"proposedPlan",proposed,"moves",moves,"gapMinutes",gap,"gapHours",BigDecimal.valueOf(gap).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP),"options",List.of("INCREASE_DAILY_TIME","CHANGE_COURSE_PRIORITY","ACCEPT_UNSCHEDULED"),"createdAt",now);jdbc.update("INSERT INTO plan_preview(id,plan_id,user_id,base_revision,as_of,snapshot,gap_minutes,input_fingerprint,created_at) VALUES(?,?,?,?,?,?,?,?,?)",preview,id,CurrentUser.idOrThrow(),base,today(),json(obj("response",result,"config",config,"segments",all,"oldConfig",oldConfig)),gap,fp,LocalDateTime.ofInstant(now,ZoneOffset.UTC));return result;}
    public Object previewGet(String id,String preview){owned(id,false);var r=jdbc.queryForList("SELECT snapshot FROM plan_preview WHERE id=? AND plan_id=? AND user_id=?",preview,id,CurrentUser.idOrThrow()).stream().findFirst().orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND));return parse(r.get("snapshot")).path("response");}
    @Transactional public Object confirm(String id,String preview,JsonNode w){input.validate("PreviewConfirm",w);learning.lockUser(CurrentUser.idOrThrow());var p=owned(id,true);var r=jdbc.queryForList("SELECT * FROM plan_preview WHERE id=? AND plan_id=? AND user_id=? FOR UPDATE",preview,id,CurrentUser.idOrThrow()).stream().findFirst().orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND));require(r.get("confirmed_at")==null,ErrorCode.CONFLICT,"预览已确认");int base=((Number)r.get("base_revision")).intValue();require(base==((Number)p.get("revision_no")).intValue()&&base==w.path("baseRevision").asInt()&&r.get("as_of").toString().equals(today().toString()),ErrorCode.CONFLICT,"原版本或预览日期已变化");JsonNode snapshot=parse(r.get("snapshot"));String fp=fingerprint(id,base,snapshot.path("oldConfig"),tasks(id));require(fp.equals(r.get("input_fingerprint"))&&fp.equals(str(w,"inputFingerprint")),ErrorCode.CONFLICT,"进度、考试日或配置已变化，请重新预览");require(((Number)r.get("gap_minutes")).intValue()==0||w.path("acceptUnscheduled").asBoolean(),ErrorCode.PLAN_GAP,"仍有未排入任务，请调整或明确接受");List<Map<String,Object>> segments=mapper.convertValue(snapshot.path("segments"),new com.fasterxml.jackson.core.type.TypeReference<List<Map<String,Object>>>(){});if(snapshot.path("configuration").asBoolean())return confirmConfiguration(id,preview,w,p,r,snapshot,base);var active=tasks(id);saveRevision(id,base+1,snapshot.path("config"),segments,Instant.now());taskIds(id,base+1,active);jdbc.update("UPDATE plan_preview SET confirmed_at=UTC_TIMESTAMP(6) WHERE id=?",preview);audit.add("PLAN_RESCHEDULE_CONFIRMED","LEARNING_PLAN",id,null,obj("baseRevision",base,"newRevision",base+1,"gapMinutes",r.get("gap_minutes")));return get(id,base+1);}

    private String taskKey(Map<String,Object> t){return t.get("courseId")+":"+t.get("kind")+":"+(t.get("itemId")!=null?t.get("itemId"):t.get("templateId"))+":"+t.get("releaseId");}
    private String configurationGuard(JsonNode config){
        List<Object> state=new ArrayList<>();for(JsonNode c:config.path("coursePriority")){var course=learning.course(c.asText());state.add(obj("course",c.asText(),"release",course.releaseId(),"exam",deadline(c.asText(),str(config,"cycleId")),"progress",jdbc.queryForList("SELECT item_id,completed,revision FROM user_item_progress WHERE user_id=? AND item_id IN (SELECT item_id FROM item_revision WHERE release_id=?) ORDER BY item_id",CurrentUser.idOrThrow(),course.releaseId())));}return json(state);
    }
    private Object configurationPreview(String id,JsonNode w){
        require(!w.has("dayCapacities")&&!w.has("coursePriority"),ErrorCode.INVALID_RELATION,"完整编辑与逾期顺延配置不能混用");
        learning.lockUser(CurrentUser.idOrThrow());var original=owned(id,true);int base=((Number)original.get("revision_no")).intValue();require(base==w.path("baseRevision").asInt(),ErrorCode.CONFLICT,"计划版本已变化");
        JsonNode config=w.path("config");validateConfig(config);var current=get(id,base);JsonNode oldConfig=mapper.valueToTree(current.get("config"));require(str(config,"cycleId").equals(str(oldConfig,"cycleId")),ErrorCode.INVALID_RELATION,"编辑计划不能更换考试周期");
        var existing=allTasks(id);Map<String,Map<String,Object>> lookup=new HashMap<>();existing.forEach(t->lookup.put(taskKey(t),t));List<Map<String,Object>> proposedTasks=new ArrayList<>();List<Map<String,Object>> newTasks=new ArrayList<>();for(var source:sourceTasks(config)){var old=lookup.get(taskKey(source));if(old!=null){source.put("id",old.get("id"));source.put("completed",old.get("completed"));source.put("completedAt",old.get("completedAt"));}else newTasks.add(source);proposedTasks.add(source);}
        var segments=allocate(config,proposedTasks,LocalDate.parse(str(config,"startDate")));int gap=segments.stream().filter(s->!s.get("state").equals("SCHEDULED")).mapToInt(s->((Number)s.get("minutes")).intValue()).sum();String preview=uuid(),fp=fingerprint(id,base,oldConfig,tasks(id));Instant now=Instant.now();var proposed=assemble(id,base+1,config,proposedTasks,segments,AdminService.instant(original,"created_at"),null);
        var result=obj("id",preview,"planId",id,"baseRevision",base,"asOf",today(),"inputFingerprint",fp,"proposedPlan",proposed,"moves",List.of(),"gapMinutes",gap,"gapHours",BigDecimal.valueOf(gap).divide(BigDecimal.valueOf(60),2,RoundingMode.HALF_UP),"options",List.of("INCREASE_DAILY_TIME","CHANGE_COURSE_PRIORITY","ACCEPT_UNSCHEDULED"),"createdAt",now);
        jdbc.update("INSERT INTO plan_preview(id,plan_id,user_id,base_revision,as_of,snapshot,gap_minutes,input_fingerprint,created_at) VALUES(?,?,?,?,?,?,?,?,?)",preview,id,CurrentUser.idOrThrow(),base,today(),json(obj("response",result,"config",config,"segments",segments,"oldConfig",oldConfig,"configuration",true,"newTasks",newTasks,"taskIds",proposedTasks.stream().map(t->t.get("id")).toList(),"guard",configurationGuard(config))),gap,fp,LocalDateTime.ofInstant(now,ZoneOffset.UTC));return result;
    }
    private Object confirmConfiguration(String id,String preview,JsonNode w,Map<String,Object> plan,Map<String,Object> previewRow,JsonNode snapshot,int base){
        require(snapshot.path("guard").asText().equals(configurationGuard(snapshot.path("config"))),ErrorCode.CONFLICT,"课程、考试日期或学习记录已变化，请重新预览");validateConfig(snapshot.path("config"));
        var oldTasks=allTasks(id);for(var revision:jdbc.queryForList("SELECT revision_no,snapshot FROM plan_revision WHERE plan_id=?",id))if(!parse(revision.get("snapshot")).has("taskIds"))taskIds(id,((Number)revision.get("revision_no")).intValue(),oldTasks);
        for(JsonNode t:snapshot.path("newTasks"))jdbc.update("INSERT INTO plan_task(id,plan_id,course_id,item_id,template_id,title_snapshot,estimated_minutes,release_id,kind,completed,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",str(t,"id"),id,str(t,"courseId"),t.path("itemId").isNull()?null:str(t,"itemId"),t.path("templateId").isNull()?null:str(t,"templateId"),str(t,"title"),t.path("estimatedMinutes").asInt(),str(t,"releaseId"),str(t,"kind"),t.path("completed").asBoolean(),t.path("completedAt").isNull()?null:LocalDateTime.ofInstant(Instant.parse(str(t,"completedAt")),ZoneOffset.UTC));
        List<Map<String,Object>> segments=mapper.convertValue(snapshot.path("segments"),new com.fasterxml.jackson.core.type.TypeReference<List<Map<String,Object>>>(){});saveRevision(id,base+1,snapshot.path("config"),segments,Instant.now());taskIds(id,base+1,scopedTasks(snapshot,allTasks(id)));jdbc.update("UPDATE learning_plan SET start_date=?,end_date=?,config_snapshot=? WHERE id=?",str(snapshot.path("config"),"startDate"),str(snapshot.path("config"),"endDate"),json(snapshot.path("config")),id);jdbc.update("UPDATE plan_preview SET confirmed_at=UTC_TIMESTAMP(6) WHERE id=?",preview);audit.add("PLAN_CONFIGURATION_CONFIRMED","LEARNING_PLAN",id,null,obj("baseRevision",base,"newRevision",base+1));return get(id,base+1);
    }
}
